"""Problemas originales. Todos los valores materiales son ficticios y didácticos."""
from pathlib import Path
import math,json
R=Path(__file__).resolve().parents[1]
P=[]
def add(key,ch,title,prompt,datos,unknown,model,hyp,eqs,steps,results,check,limits,tests):
 P.append(dict(key=key,ch=ch,title=title,prompt=prompt,datos=datos,unknown=unknown,model=model,hyp=hyp,eqs=eqs,steps=steps,results=results,check=check,limits=limits,tests=tests))
def test(expr,expected,unit='dimensionless',symbolic=None,units=None):return dict(expression=expr,expected=expected,unit=unit,symbolic=symbolic,symbol_units=units)
pi=math.pi
add('P01',2,'Carga axial y elongación','Una probeta ficticia de sección uniforme recibe tracción axial centrada. Determine su respuesta elástica y explique qué propiedad faltaría para comprobar que no cede.',r'$F=8{,}4\,\mathrm{kN}$; $A=70\,\mathrm{mm^2}$; $L_0=180\,\mathrm{mm}$; $E=72\,\mathrm{GPa}$.','Tensión nominal, deformación y elongación.','Barra uniaxial elástica lineal.','Pequeñas deformaciones; sección constante; sin efectos térmicos; análisis lejos de los extremos.',[r'\sigma=F/A,\quad\varepsilon=\sigma/E,\quad\Delta L=FL_0/(AE).'],[r'El área en SI es $70\times10^{-6}\,\mathrm{m^2}$. Se mantiene la misma sección para tensión y rigidez.',r'$\sigma=8400/(70\times10^{-6})$; $\varepsilon=120\times10^6/(72\times10^9)$; $\Delta L=\varepsilon(0{,}180)$.'],r'$\sigma=120\,\mathrm{MPa}$, $\varepsilon=1{,}6667\times10^{-3}$, $\Delta L=0{,}300\,\mathrm{mm}$.','La sustitución inversa da fuerza 8400 N y la razón elongación/longitud coincide con la deformación. La elongación es positiva para tracción.','Falta límite elástico y no se evalúan entallas, temperatura, fatiga ni dispersión.',[test('8400/(70e-6)',120e6,'Pa','F/A',{'F':'N','A':'m^2'}),test('8400*.18/(70e-6*72e9)',.0003,'m','F*L/(A*E)',{'F':'N','L':'m','A':'m^2','E':'Pa'})])
add('P02',2,'Dilatación impedida','Una barra ficticia se calienta uniformemente con sus extremos impedidos de desplazarse. Compare la dilatación libre y la tensión del modelo totalmente restringido.',r'$L=0{,}40\,\mathrm m$; $E=110\,\mathrm{GPa}$; $\alpha=9{,}0\times10^{-6}\,\mathrm{K^{-1}}$; $\Delta T=80\,\mathrm K$.','Elongación libre y tensión axial con restricción total.','Compatibilidad térmica y elasticidad uniaxial.','Temperatura uniforme; apoyos rígidos; propiedades constantes; se supone régimen elástico y no se estudia pandeo.',[r'\varepsilon=\sigma/E+\alpha\Delta T=0,\quad\sigma=-E\alpha\Delta T,\quad\Delta L_{libre}=\alpha\Delta T L.'],[r'En libre expansión, $\Delta L=9\times10^{-6}(80)(0{,}40)$.',r'Con extremos fijos, la deformación mecánica compensa la térmica: $\sigma=-110\times10^9(9\times10^{-6})(80)$.'],r'$\Delta L_{libre}=0{,}288\,\mathrm{mm}$; $\sigma=-79{,}2\,\mathrm{MPa}$ (compresión).','Al sustituir la tensión, la suma de deformación mecánica y térmica es cero. Si la temperatura no cambia, desaparecen ambas contribuciones.','La restricción real puede ser flexible; la plasticidad, fluencia y pandeo pueden cambiar la solución.',[test('9e-6*80*.4',.000288,'m','alpha*dT*L',{'alpha':'1/K','dT':'K','L':'m'}),test('-110e9*9e-6*80',-79.2e6,'Pa','-E*alpha*dT',{'E':'Pa','alpha':'1/K','dT':'K'})])
add('P03',2,'Tensiones principales y von Mises','Se proporciona un estado plano uniforme en un punto. Obtenga tensiones principales y equivalente de von Mises; determine el cociente frente a un límite elástico supuesto.',r'$\sigma_x=150$, $\sigma_y=-30$, $\tau_{xy}=40\,\mathrm{MPa}$; $\sigma_y^{mat}=300\,\mathrm{MPa}$.','Dos tensiones principales en el plano y equivalente.','Autovalores de tensor simétrico y cedencia de von Mises.','Tensión plana; material isótropo dúctil compatible con el criterio; pequeñas deformaciones.',[r'\sigma_{1,2}=60\pm\sqrt{90^2+40^2}\ \mathrm{MPa}.',r'\sigma_{VM}=\sqrt{150^2-150(-30)+(-30)^2+3(40)^2}\ \mathrm{MPa}.'],[r'La media es $(150-30)/2=60$ MPa y el radio del círculo de Mohr es $\sqrt{9700}$ MPa.',r'El tercer valor principal es cero por tensión plana; se ordenan los tres si se estudia un criterio tridimensional.'],r'$\sigma_1=158{,}489$, $\sigma_2=-38{,}489\,\mathrm{MPa}$; $\sigma_{VM}=180{,}831\,\mathrm{MPa}$; cociente $1{,}659$.','La suma de principales del plano es 120 MPa, igual a la traza original; el determinante del bloque también se conserva.','El cociente no es un margen frente a grietas ni fatiga. La notación del límite material se distingue de la componente y.',[test('60+sqrt(9700)',60+math.sqrt(9700),'MPa'),test('sqrt(150**2-150*(-30)+(-30)**2+3*40**2)',math.sqrt(32700),'MPa')])
add('P04',2,'Pared delgada: dos direcciones de carga','Un cilindro cerrado idealizado recibe presión interna. Calcule tensiones de membrana y von Mises, explicando por qué no son iguales las tensiones circunferencial y longitudinal.',r'$p=2{,}0\,\mathrm{MPa}$; $r=50\,\mathrm{mm}$; $t=1{,}0\,\mathrm{mm}$.','Tensión circunferencial, axial y equivalente.','Equilibrio de membrana en cilindro de pared delgada.','Radio medio; presión uniforme; extremos cerrados; sin concentraciones ni flexión local; tensión radial despreciable.',[r'\sigma_\theta=pr/t,\quad\sigma_z=pr/(2t),\quad\sigma_{VM}=\sqrt{\sigma_\theta^2-\sigma_\theta\sigma_z+\sigma_z^2}.'],[r'$r/t=50$ permite explorar la aproximación de pared delgada, aunque su aceptabilidad depende de la precisión exigida.',r'$\sigma_\theta=2\times10^6(0{,}05)/0{,}001$ y $\sigma_z=\sigma_\theta/2$.'],r'$\sigma_\theta=100\,\mathrm{MPa}$; $\sigma_z=50\,\mathrm{MPa}$; $\sigma_{VM}=86{,}603\,\mathrm{MPa}$.','El equilibrio axial recupera la fuerza de presión sobre el extremo. Si p tiende a cero, las tensiones se anulan.','No se evalúan cierres, discontinuidades, ciclos, plasticidad ni un recipiente real.',[test('2e6*.05/.001',100e6,'Pa','p*r/t',{'p':'Pa','r':'m','t':'m'}),test('sqrt(100**2-100*50+50**2)',math.sqrt(7500),'MPa')])
add('P05',2,'Energía elástica almacenada','Una pieza de volumen uniforme se idealiza bajo tensión uniaxial. Determine la energía elástica por volumen y la energía total.',r'$\sigma=160\,\mathrm{MPa}$; $E=80\,\mathrm{GPa}$; $V=12\,\mathrm{cm^3}$.','Densidad de energía y energía.','Integración del trabajo en elasticidad lineal.','Carga uniaxial uniforme y reversible; sin energía plástica ni térmica.',[r'u=\int_0^{\varepsilon}E\eta\,d\eta=\sigma^2/(2E),\quad U=uV.'],[r'$V=12\times10^{-6}\,\mathrm{m^3}$; $u=(160\times10^6)^2/(2\cdot80\times10^9)$.'],r'$u=160\,000\,\mathrm{J/m^3}$; $U=1{,}92\,\mathrm J$.',r'El área triangular $\sigma\varepsilon/2$ coincide con u. Las unidades de presión equivalen a energía por volumen.','No representa tenacidad a fractura ni energía total absorbida hasta rotura.',[test('(160e6)**2/(2*80e9)',160000,'Pa','sigma**2/(2*E)',{'sigma':'Pa','E':'Pa'}),test('160000*12e-6',1.92,'J')])
add('P06',2,'Sensibilidad a entalla','Una probeta tiene un concentrador elástico y una sensibilidad a entalla especificada para el ejercicio. Compare amplificación elástica y factor efectivo de fatiga.',r'$K_t=2{,}4$; $q=0{,}70$; amplitud nominal $\sigma_a=60\,\mathrm{MPa}$.','Factor Kf y amplitudes de comparación.','Modelo empírico de sensibilidad a entalla.','El valor de q es un dato ficticio válido solo para esta situación; la curva de referencia corresponde a material sin ese detalle.',[r'K_f=1+q(K_t-1),\quad\sigma_{a,f}=K_f\sigma_a,\quad\sigma_{a,el}=K_t\sigma_a.'],[r'$K_f=1+0{,}70(2{,}4-1)=1{,}98$. Se aplican los factores una sola vez.'],r'$K_f=1{,}98$; $\sigma_{a,f}=118{,}8\,\mathrm{MPa}$; pico elástico de amplitud $144\,\mathrm{MPa}$.','Con q=0 resulta Kf=1 y con q=1 resulta Kf=Kt; ambos límites se satisfacen.','Kf no predice el campo local de plasticidad ni debe aplicarse de nuevo si la curva ya corresponde a la pieza entallada.',[test('1+.7*(2.4-1)',1.98),test('(1+.7*(2.4-1))*60',118.8,'MPa')])
add('P07',3,'Intensidad aplicada a una grieta de borde','Se idealiza una grieta de borde bajo tracción. Compare la intensidad con una tenacidad supuesta aplicable y explique el alcance de la comparación.',r'$a=1{,}8\,\mathrm{mm}$ (longitud desde el borde); $Y=1{,}12$ constante; $\sigma=210\,\mathrm{MPa}$; $K_{IC}=42\,\mathrm{MPa\sqrt m}$.','KI y cociente KI/KIC.','MFEL de modo I con factor geométrico dado.','Pequeña plastificación y tenacidad de deformación plana asumidas; carga remota; no crecimiento subcrítico.',[r'K_I=Y\sigma\sqrt{\pi a}.'],[r'$a=0{,}0018$ m. Se calcula $1{,}12(210)\sqrt{\pi(0{,}0018)}$ usando MPa y m.'],fr'$K_I={1.12*210*math.sqrt(pi*.0018):.4f}\,\mathrm{{MPa\sqrt m}}$; $K_I/K_{{IC}}={1.12*210*math.sqrt(pi*.0018)/42:.4f}$.',r'Elevar al cuadrado permite comprobar $K_I^2/(Y^2\sigma^2)=\pi a$. La comparación resulta inferior a uno dentro del modelo.','No se han comprobado espesor ni fatiga o corrosión; no es criterio de aceptación en servicio.',[test('1.12*210*sqrt(pi*.0018)',1.12*210*math.sqrt(pi*.0018),'MPa*m^0.5','Y*sigma*sqrt(pi*a)',{'Y':'dimensionless','sigma':'Pa','a':'m'})])
add('P08',3,'Tamaño crítico y longitud total','Una placa muy ancha contiene una grieta central pasante. Calcule el tamaño crítico y la tensión crítica para un defecto inicial, conservando la definición de semilongitud.',r'$K_{IC}=36\,\mathrm{MPa\sqrt m}$; $\sigma=240\,\mathrm{MPa}$; $Y=1$; longitud total inicial $2a_i=3\,\mathrm{mm}$.','ac,2ac y tensión crítica para ai.','Criterio estático KI=KIC en MFEL.','Y constante; tenacidad aplicable; carga uniforme y pequeña zona plástica.',[r'a_c=(K_{IC}/\sigma)^2/\pi,\quad \sigma_c=K_{IC}/\sqrt{\pi a_i}.'],[r'Se usa $a_i=0{,}0015$ m; no se introduce 0,003 m en la raíz.',r'$a_c=(36/240)^2/\pi$ m y $\sigma_c=36/\sqrt{\pi(0{,}0015)}$ MPa.'],fr'$a_c={((36/240)**2/pi)*1000:.4f}\,\mathrm{{mm}}$; $2a_c={2*((36/240)**2/pi)*1000:.4f}\,\mathrm{{mm}}$; $\sigma_c={36/math.sqrt(pi*.0015):.3f}\,\mathrm{{MPa}}$.','Sustituir ac en KI recupera36 MPa√m. Al duplicar tensión se reduce ac a un cuarto si Y se mantiene.','Falta comprobar cedencia, ligamento y espesor; no hay crecimiento por fatiga en esta solución.',[test('(36/240)**2/pi',(36/240)**2/pi,'m','(K/sigma)**2/pi',{'K':'Pa*m^0.5','sigma':'Pa'}),test('36/sqrt(pi*.0015)',36/math.sqrt(pi*.0015),'MPa')])
add('P09',3,'Cribado de deformación plana','Se dispone de un valor candidato de tenacidad y una chapa. Calcule la dimensión de cribado y compruebe si el espesor la satisface.',r'$K=48\,\mathrm{MPa\sqrt m}$; $\sigma_y=900\,\mathrm{MPa}$; $B=5\,\mathrm{mm}$.','Dimensión 2,5(K/sigma_y)^2 y comparación.','Condición dimensional de cribado de validez de tenacidad plana.','Se utiliza como condición necesaria de estudio; no como certificación de ensayo normalizado.',[r'\ell_{min}=2{,}5(K/\sigma_y)^2.'],[r'$\ell_{min}=2{,}5(48/900)^2=0{,}0071111$ m.'],r'$\ell_{min}=7{,}111\,\mathrm{mm}>B=5\,\mathrm{mm}$; el espesor no satisface el cribado.','El cociente tiene unidades de raíz de longitud; su cuadrado es longitud.','Faltan condiciones de probeta, ligamento,carga y norma. No se debe denominar KIC válido al valor candidato solo por disponer de él.',[test('2.5*(48/900)**2',2.5*(48/900)**2,'m','2.5*(K/sigma)**2',{'K':'Pa*m^0.5','sigma':'Pa'})])
# Factor de anchura y raíz implícita.
lo=1e-9;hi=.04-1e-9
for _ in range(100):
 mid=(lo+hi)/2;k=180*math.sqrt(pi*mid/math.cos(pi*mid/.08))
 if k>30:hi=mid
 else:lo=mid
ac=(lo+hi)/2
add('P10',3,'Factor geométrico variable','Una solución idealizada de placa de anchura total W utiliza el factor especificado. Obtenga la semilongitud crítica por resolución implícita y compárela con Y=1.',r'$W=80\,\mathrm{mm}$; $\sigma=180\,\mathrm{MPa}$; $K_{IC}=30\,\mathrm{MPa\sqrt m}$; $Y=\sqrt{\sec(\pi a/W)}$; $0<a<W/2$.','Raíz ac y comparación de anchura infinita.','MFEL con solución geométrica expresamente dada.','Placa central pasante; convención W de anchura total; dominio de Y indicado; pequeña plastificación supuesta.',[r'180\sqrt{\pi a/\cos(\pi a/0{,}08)}=30.'],[r'Se busca la raíz en $(0,0{,}04)$ m. La función crece en ese intervalo y diverge en el extremo superior.',r'La aproximación Y=1 da $a_{c,\infty}=(30/180)^2/\pi$.'],fr'$a_c={ac*1000:.5f}\,\mathrm{{mm}}$; con $Y=1$, $a_{{c,\infty}}={(30/180)**2/pi*1000:.5f}\,\mathrm{{mm}}$.','La sustitución de la raíz en la expresión completa recupera30MPa√m; el tamaño finito es menor porque Y>1. Se comprueba ac<W/2.','No se extrapola esta solución a una grieta de borde, superficie, otro sistema de carga o plasticidad extensa.',[test(f'180*sqrt(pi*{ac!r}/cos(pi*{ac!r}/.08))',30,'MPa*m^0.5')])
add('P11',4,'Carga repetida y Goodman','Una probeta se carga desde cero hasta un máximo positivo. Use el criterio de Goodman dado para hallar el máximo nominal compatible con el límite de la aproximación.',r'$S_e=240\,\mathrm{MPa}$; $S_u=800\,\mathrm{MPa}$; $R=0$; sin factor de entalla.','Tensión máxima y amplitud.','Goodman lineal con tensión media de tracción.','Datos ficticios para condiciones compatibles; no plasticidad y no factor de seguridad adicional.',[r'\sigma_a=\sigma_m=\sigma_{max}/2,\quad\sigma_{max}=2/(1/S_e+1/S_u).'],[r'La condición se plantea en amplitud y media, no introduciendo el máximo en ambos términos.',r'$\sigma_{max}=2/(1/240+1/800)$ MPa.'],r'$\sigma_{max}=369{,}231\,\mathrm{MPa}$; $\sigma_a=\sigma_m=184{,}615\,\mathrm{MPa}$.','La suma de los dos cocientes de Goodman es1. Con media nula el criterio recuperaría amplitudSe.','No representa vida infinita en corrosión ni una curva específica de pieza; Goodman es aproximación.',[test('2/(1/240+1/800)',2/(1/240+1/800),'MPa')])
b=math.log(220/400)/math.log(1e6/1e4);A=400/1e4**b;N=(280/A)**(1/b)
add('P12',4,'Ajuste de una ley S–N','Dos puntos ficticios de una curva completamente alternante se ajustan por una recta en logaritmos. Obtenga coeficientes y vida interpolada a otra amplitud.',r'$(N_1,\sigma_{a1})=(10^4,400\,\mathrm{MPa})$; $(N_2,\sigma_{a2})=(10^6,220\,\mathrm{MPa})$; amplitud objetivo280MPa.','A,b y ciclos.','Basquin en convención sigma_a=A N^b (ciclos, no reversiones).','R=-1; misma superficie y temperatura; se interpola dentro del dominio de los dos datos.',[r'b=\ln(\sigma_{a2}/\sigma_{a1})/\ln(N_2/N_1),\quad A=\sigma_{a1}/N_1^b,\quad N=(280/A)^{1/b}.'],[r'Se calculan cocientes adimensionales para obtener b y se conserva la convención de ciclos.'],fr'$b={b:.6f}$; $A={A:.4f}\,\mathrm{{MPa}}$; $N={N:.1f}$ ciclos.','Sustituir10^4y10^6recupera400y220MPa. El resultado objetivo queda entre ambas vidas.','Dos puntos no describen dispersión ni justifican extrapolar; no se aplica con otra razónR sin corrección.',[test('log(220/400)/log(1e6/1e4)',b),test(f'(280/{A!r})**(1/{b!r})',N)])
add('P13',4,'Miner con un nivel restante','Un bloque contiene una contribución conocida y otra desconocida. Determine cuántos ciclos del segundo nivel completan el daño lineal unitario.',r'$n_1=18\,000$, $N_1=120\,000$; $N_2=30\,000$; criterio $D=1$.','n2.','Acumulación lineal de Miner.','Niveles de carga definidos por vidas de referencia compatibles; no interacción ni efecto de secuencia.',[r'n_1/N_1+n_2/N_2=1,\quad n_2=N_2(1-n_1/N_1).'],[r'El primer nivel consume $18000/120000=0{,}15$. Queda daño lineal0,85.'],r'$n_2=25\,500$ ciclos.','La suma0,15+25500/30000es1; n2esmenorqueN2.','La igualdadD=1no es una fecha determinista de fallo real y no representa el orden de los niveles.',[test('30000*(1-18000/120000)',25500)])
add('P14',4,'Bloques y acumulación','Una misión ficticia repite dos niveles. Calcule daño por misión y número de misiones completas antes del criterio lineal.',r'$n_1=120$, $N_1=60\,000$; $n_2=30$, $N_2=10\,000$.','Daño y misiones.','Miner con bloques idénticos.','Datos del mismo modelo de vida; secuencia no representada; sin dispersión.',[r'D_b=120/60000+30/10000,\quad B=1/D_b.'],[r'Se suma la contribución de cada nivel; no se promedian directamente las dos vidas.'],r'$D_b=0{,}005$; $B=200$ misiones al criterio. Tras199, $D=0{,}995$.','Multiplicar200por0,005recupera1. La suma de fracciones es adimensional.','El umbral académico no implica autorización para volar199misiones; faltan márgenes y validación física.',[test('120/60000+30/10000',.005),test('1/(120/60000+30/10000)',200)])
add('P15',4,'K máximo y rango de intensidad','Se idealiza una grieta sometida a carga cíclica de tracción. Calcule las intensidades y distinga las comprobaciones de crecimiento e inestabilidad.',r'$a=2{,}5\,\mathrm{mm}$; $Y=1{,}1$; $\sigma_{max}=200$ y $\sigma_{min}=40\,\mathrm{MPa}$; $K_{IC}=35\,\mathrm{MPa\sqrt m}$.','Kmax,Kmin,DeltaK yR.','MFEL lineal sin cierre de grieta.','Ambos extremos de carga en tracción; Y y a constantes durante el ciclo; tenacidad supuesta aplicable.',[r'K_{max,min}=Y\sigma_{max,min}\sqrt{\pi a},\quad\Delta K=Y(\sigma_{max}-\sigma_{min})\sqrt{\pi a}.'],[r'El rango de tensión es160MPa y la amplitud80MPa. Se usa el rango paraDeltaK.'],fr'$K_{{max}}={1.1*200*math.sqrt(pi*.0025):.4f}$; $K_{{min}}={1.1*40*math.sqrt(pi*.0025):.4f}$; $\Delta K={1.1*160*math.sqrt(pi*.0025):.4f}\,\mathrm{{MPa\sqrt m}}$; $R=0{{,}}20$.','Kmin/Kmax=R y Kmax−Kmin=DeltaK. KmaxesmenorqueKICdentrodelmodelo.','DeltaKpositivo no garantiza que Paris sea válido: se necesita dominio, umbral,Rycondiciones. La comparación estática no excluye crecimiento.',[test('1.1*200*sqrt(pi*.0025)',1.1*200*math.sqrt(pi*.0025),'MPa*m^0.5'),test('1.1*160*sqrt(pi*.0025)',1.1*160*math.sqrt(pi*.0025),'MPa*m^0.5')])
C=2e-12;ds=110.;ai=.001;af=.006;Np=2*(ai**-.5-af**-.5)/(C*(ds*math.sqrt(pi))**3)
add('P16',4,'Vida de propagación: Paris m=3','Una grieta central idealizada crece en la región de Paris. Calcule ciclos entre dos semilongitudes. El objetivo es vida de propagación, no vida total desde material sin defecto.',r'$a_i=1{,}0\,\mathrm{mm}$; $a_f=6{,}0\,\mathrm{mm}$; $Y=1$; $\Delta\sigma=110\,\mathrm{MPa}$; $m=3$; $C=2\times10^{-12}\,\mathrm{m/ciclo}/(\mathrm{MPa\sqrt m})^3$.','CiclosN.','Paris con rango constante yYconstante.','Grieta larga; región intermedia válida durante todo el intervalo supuesto; sin cierre,retardosniiniciación. El estado final se supone admisible por un criterio independiente.',[r'N=\frac{2(a_i^{-1/2}-a_f^{-1/2})}{C(\Delta\sigma\sqrt\pi)^3}.'],[r'Se usa metros para a y MPa para tensión porque esa es la calibración de C.',r'$N=2(0{,}001^{-1/2}-0{,}006^{-1/2})/[2\times10^{-12}(110\sqrt\pi)^3]$.'],fr'$N={Np:.1f}$ ciclos de propagación.','La derivada de la primitiva reproduce a^(−3/2); una cuadratura numérica independiente se registra en el informe. Ncrece al reducirDeltaSigma.','No se ha comprobado Kmax contra tenacidad ni POD de la inspección; no es intervalo autorizado.',[test('2*(.001**(-.5)-.006**(-.5))/(2e-12*(110*sqrt(pi))**3)',Np)])
N2=math.log(.005/.0008)/(5e-10*(90*math.sqrt(pi))**2)
add('P17',4,'Paris m=2: el caso logarítmico','Calcule vida entre dos tamaños para una ley de Paris con exponente2 y explique por qué no se usa la expresión de potencia con denominador1−m/2.',r'$a_i=0{,}8\,\mathrm{mm}$; $a_f=5\,\mathrm{mm}$; $Y=1$; $\Delta\sigma=90\,\mathrm{MPa}$; $m=2$; $C=5\times10^{-10}\,\mathrm{m/ciclo}/(\mathrm{MPa\sqrt m})^2$.','N.','Integración de da/[C(DeltaK)^2].','Región de Paris y condiciones constantes asumidas; mismos límites físicos que P16.',[r'N=\frac{\ln(a_f/a_i)}{C(\Delta\sigma\sqrt\pi)^2}.'],[r'El integrando contiene1/a; su integral eslogaritmo. El cocientea_f/a_iesadimensional.'],fr'$N={N2:.1f}$ ciclos.','La cuadratura del integrando coincide con el logaritmo. Siaf=ai,log1=0yN=0.','Los coeficientes no se reutilizan para otro exponente o sistema de unidades.',[test('log(.005/.0008)/(5e-10*(90*sqrt(pi))**2)',N2)])
Ni=2*(.0007**-.5-.004**-.5)/(1.5e-12*(100*math.sqrt(pi))**3)
add('P18',4,'Un intervalo de inspección académico','Una grieta detectable idealizada crece hasta un tamaño final previamente fijado. Estime vida de propagación y un intervalo académico del40% de esa vida.',r'$a_i=0{,}7\,\mathrm{mm}$; $a_f=4\,\mathrm{mm}$; $Y=1$; $\Delta\sigma=100\,\mathrm{MPa}$; $C=1{,}5\times10^{-12}\,\mathrm{m/ciclo}/(\mathrm{MPa\sqrt m})^3$; $m=3$.','Vida de propagación e intervalo académico.','Paris y fracción de vida expresamente impuesta por el ejercicio.','Región de Paris supuesta; tamaño inicial no representa una POD validada; el factor0,4no es reglamentario.',[r'N=2(a_i^{-1/2}-a_f^{-1/2})/[C(\Delta\sigma\sqrt\pi)^3],\quad I=0{,}4N.'],[r'Se convierten semilongitudes a metros y se integra antes de aplicar la fracción. Se redondea hacia abajo si se necesita un número entero de ciclos.'],fr'$N={Ni:.1f}$ ciclos; $I={.4*Ni:.1f}$ ciclos, o {math.floor(.4*Ni)} ciclos enteros redondeados hacia abajo.','La fracción del intervalo respecto a la vida calculada es0,4. Una integración numérica independiente contrasta la vida.','No se define un intervalo real sin espectro,tenacidad,probabilidad de detección,dispersión y aprobación aplicable.',[test('2*(.0007**(-.5)-.004**(-.5))/(1.5e-12*(100*sqrt(pi))**3)',Ni)])
add('P19',5,'Sensibilidad a tensión de fluencia','A temperatura constante, una ley normalizada de Norton predice la tasa secundaria. Obtenga la tasa y la deformación acumulada durante una permanencia.',r'$\dot\varepsilon_1=2\times10^{-8}\,\mathrm{s^{-1}}$ a $\sigma_1=200\,\mathrm{MPa}$; $n=5$; $\sigma_2=240\,\mathrm{MPa}$; permanencia20h.','Tasa2 e incremento de deformación.','Norton a temperatura fija en un mecanismo dado.','Misma microestructura y régimen; solo tramo secundario; tensión constante durante20h.',[r'\dot\varepsilon_2=\dot\varepsilon_1(\sigma_2/\sigma_1)^n,\quad\Delta\varepsilon=\dot\varepsilon_2 t.'],[r'La razón es$(240/200)^5=2{,}48832$. Las20h equivalen a72000s.'],r'$\dot\varepsilon_2=4{,}97664\times10^{-8}\,\mathrm{s^{-1}}$; $\Delta\varepsilon=0{,}00358318$ (0,3583%).','La razón es adimensional; tasa por tiempo da deformación. Al igualar tensiones se recupera la tasa inicial.','No incluye fluencia primaria/terciaria,temperatura variable ni tiempo a rotura.',[test('2e-8*(240/200)**5',4.97664e-8,'1/s'),test('2e-8*(240/200)**5*20*3600',.0035831808)])
ratio=math.exp(-220000/8.314462618*(1/980-1/930))
add('P20',5,'Sensibilidad conjunta a tensión y temperatura','Una ley de Norton–Arrhenius se expresa por cociente respecto a un estado de referencia. Calcule la tasa al cambiar tensión y temperatura.',r'$\dot\varepsilon_1=10^{-8}\,\mathrm{s^{-1}}$; $T_1=930\,\mathrm K$, $T_2=980\,\mathrm K$; $\sigma_1=180$, $\sigma_2=200\,\mathrm{MPa}$; $n=4$; $Q=220\,\mathrm{kJ/mol}$.','Razón de tasas y tasa2.','Activación térmica con un único mecanismo.','MismoQ,n y estado; constantes con unidades coherentes; temperatura absoluta.',[r'\dot\varepsilon_2/\dot\varepsilon_1=(200/180)^4\exp[-220000/R(1/980-1/930)].'],[r'El incremento térmico hace positivo el exponente completo. Se usa$R=8{,}314462618\,\mathrm{J/(mol\,K)}$.'],fr'Factor térmico{ratio:.5f}; razón total{ratio*(200/180)**4:.5f}; $\dot\varepsilon_2={1e-8*ratio*(200/180)**4:.7g}\,\mathrm{{s^{{-1}}}}$.','La tasa aumenta por ambos cambios. El exponente es adimensional y la temperatura no se introduce en gradosCelsius.','No se extrapola a una transición de mecanismo ni se deduce tiempo a rotura de una tasa aislada.',[test('exp(-220000/8.314462618*(1/980-1/930))*(200/180)**4',ratio*(200/180)**4)])
tlm=10**((900/950)*(20+math.log10(10000))-20)
add('P21',5,'Larson–Miller a tensión fija','Una correlación ficticia de rotura se considera válida en dos temperaturas a igual tensión. Estime el tiempo equivalente y compruebe el parámetro.',r'$T_1=900\,\mathrm K$; $t_1=10000\,\mathrm h$; $T_2=950\,\mathrm K$; $C_{LM}=20$, calibrado con horas.','t2 yP.','Igualdad del parámetro Larson–Miller a tensión fija.','Mismo material,estado,mecanismo y tensión; correlación supuesta válida.',[r'P=T_1(C_{LM}+\log_{10}t_1),\quad \log_{10}t_2=P/T_2-C_{LM}.'],[r'$P=900(20+4)=21600$ K. Después,$\log_{10}t_2=21600/950-20$.'],fr'$t_2={tlm:.4f}\,\mathrm h$; $P=21600\,\mathrm K$.','Sustituir t2con horas recuperaP. A mayor temperatura,menor tiempo equivalente en el ajuste.','No cambiar horas por segundos conservandoC; no es una extensión de vida de un componente real.',[test('10**(21600/950-20)',tlm,'h')])
time=(.0012-.0005)/(2e-8)
add('P22',5,'Elasticidad inicial y deformación de fluencia','Una barra puede alcanzar una deformación total máxima ficticia. Separe la contribución elástica inicial y el tiempo para agotar el margen por fluencia secundaria.',r'$\sigma=100\,\mathrm{MPa}$; $E=200\,\mathrm{GPa}$; $\varepsilon_{lim}=0{,}0012$; $\dot\varepsilon_s=2\times10^{-8}\,\mathrm{s^{-1}}$ a la temperatura fija del ensayo900K.','Deformación elástica, margen y tiempo.','Suma de elasticidad lineal y fluencia secundaria constante.','Carga y temperatura constantes; no primaria/terciaria; la tasa se asume válida durante todo el intervalo.',[r'\varepsilon_e=\sigma/E,\quad t=(\varepsilon_{lim}-\varepsilon_e)/\dot\varepsilon_s.'],[r'$\varepsilon_e=100\times10^6/(200\times10^9)=0{,}0005$. Queda deformación0,0007.'],fr'$t={time:.0f}\,\mathrm s={time/3600:.5f}\,\mathrm h$.','Al sumar0,0005+2e−8·35000se recupera0,0012. La diferencia debe ser positiva antes de dividir.','Si el límite fuera menor que la deformación inicial,no existiría un tiempo positivo disponible. No se predice rotura.',[test('(0.0012-100e6/200e9)/(2e-8)',35000,'s')])
EL=.58*240+.42*3.5;rho=.58*1800+.42*1200
add('P23',9,'Módulo longitudinal y masa de un compuesto','Una lámina unidireccional ideal tiene unión perfecta y fibras continuas. Calcule módulo longitudinal,densidad y módulo específico.',r'$V_f=0{,}58$; $E_f=240$, $E_m=3{,}5\,\mathrm{GPa}$; $\rho_f=1800$, $\rho_m=1200\,\mathrm{kg/m^3}$.','EL,rho yEL/rho.','Regla de mezcla longitudinal y densidad sin vacíos.','Isodeformación longitudinal; fases lineales; sin porosidad; no se calcula resistencia a rotura.',[r'E_L=V_fE_f+(1-V_f)E_m,\quad\rho=V_f\rho_f+(1-V_f)\rho_m.'],[r'$E_L=0{,}58(240)+0{,}42(3{,}5)$ GPa y$\rho=0{,}58(1800)+0{,}42(1200)$.'],fr'$E_L={EL:.3f}\,\mathrm{{GPa}}$; $\rho={rho:.1f}\,\mathrm{{kg/m^3}}$; $E_L/\rho={EL*1e9/rho:.6g}\,\mathrm{{m^2/s^2}}$.','Ambas propiedades quedan entre las de las fases. ConVf=0se recuperan propiedades de matriz.','El cociente no predice por sí solo rigidez de un panelniotros modos de carga; no se atribuye a producto real.',[test('.58*240+.42*3.5',EL,'GPa'),test('.58*1800+.42*1200',rho,'kg/m^3')])
ET=1/(.58/240+.42/3.5)
add('P24',9,'Modelo transversal en serie','Con las fases del problemaP23, evalúe la idealización de igual tensión y explique por qué no debe presentarse como módulo transversal exacto de cualquier lámina.',r'$V_f=0{,}58$; $E_f=240$ y $E_m=3{,}5\,\mathrm{GPa}$.','ET en la idealización.','Acoplamiento en serie con igual tensión.','Geometría idealizada; elasticidad de fases; se ignoran campos no uniformes e interfaces reales.',[r'1/E_T=V_f/E_f+(1-V_f)/E_m.'],[r'$E_T=1/[0{,}58/240+0{,}42/3{,}5]$ GPa.'],fr'$E_T={ET:.5f}\,\mathrm{{GPa}}$; cociente$E_L/E_T={EL/ET:.3f}$.','La rigidez transversal idealizada es muy inferior a la longitudinaly permanece entre los módulos de las fases.','La aproximación de serie puede ser poco representativa; se requieren modelos o ensayos para una lámina real.',[test('1/(.58/240+.42/3.5)',ET,'GPa')])
EI=2*70e9*.04*.001*(.03**2/4+.001**2/12);EI0=70e9*.04*(.002)**3/12
add('P25',9,'Rigidez ideal de un sándwich','Compare dos caras separadas con una placa monolítica que tiene la misma cantidad de material de cara por longitud. Ignore masa y rigidez longitudinal del núcleo,pero declare las limitaciones.',r'$E=70\,\mathrm{GPa}$; ancho$b=40\,\mathrm{mm}$; espesor de cada cara$t=1\,\mathrm{mm}$; distancia entre centroides$h=30\,\mathrm{mm}$.','EI y comparacióncon placa de espesor2t.','Flexión lineal de sección compuesta y teorema de ejes paralelos.','Unión perfecta; núcleo mantiene separación; se ignora cortadura del núcleo,inestabilidad y masa del mismo.',[r'EI=2E[bt^3/12+bt(h/2)^2],\quad EI_0=Eb(2t)^3/12.'],[r'Se calcula la inercia local de cada cara y la debida a su separación; no se usa hcomo espesor macizo.'],fr'$EI={EI:.4f}\,\mathrm{{N\,m^2}}$; $EI_0={EI0:.5f}\,\mathrm{{N\,m^2}}$; razón{EI/EI0:.2f}.','Ambas expresiones tienen unidades de rigidez a flexión. Si h=t,las carascontiguas recuperan la inercia de espesor2t.','No se comprueban cortadura,aplastamiento,arrugamiento ni despegue. La comparación de masa excluye explícitamente el núcleo.',[test('2*70e9*.04*.001*(.03**2/4+.001**2/12)',EI,'N*m^2','E*b*t*(h**2/2+t**2/6)',{'E':'Pa','b':'m','t':'m','h':'m'})])
x=math.sqrt(3e-16*250*3600)
add('P26',6,'Oxidación parabólica','Una correlación de espesor de óxido se considera válida a temperatura fija. Calcule espesor y tiempo para alcanzar el doble.',r'$x_0=0$; $k_p=3\times10^{-16}\,\mathrm{m^2/s}$; $t=250\,\mathrm h$.','x y tiempo para2x.','Crecimiento parabólico isotermo x²=kp t.','Mismo mecanismo y ambiente; no desprendimiento; xesespesor de óxido,no pérdida de metal.',[r'x=\sqrt{k_pt},\quad t(2x)=4t(x).'],[r'$t=900000$ s. Se calcula la raíz después de convertir tiempo.'],fr'$x={x*1e6:.5f}\,\mu\mathrm m$; doble espesor a1000h.','x²/t recuperakp. El tiempo aumenta con el cuadrado del espesor en esta ley.','Faltan datos para convertir espesor en pérdida de sustrato o vida de protección.',[test('sqrt(3e-16*250*3600)',x,'m','sqrt(k*t)',{'k':'m^2/s','t':'s'})])
add('P27',11,'Ultrasonidos y tiempo de ida y vuelta','En un modelo pulso-eco,la señal de un reflector vuelve tras el tiempo medido. Calcule profundidad y explique el factor2.',r'$v=5900\,\mathrm{m/s}$; retraso relativo$t=8{,}0\,\mu\mathrm s$.','Profundidadd.','Propagación recta y velocidad constante.','Se descontó tiempo de acoplamiento; haz normal; trayectoria de ida y vuelta; material homogéneo.',[r'd=vt/2.'],[r'$d=5900(8\times10^{-6})/2$. La señal recorre dos veces la profundidad.'],r'$d=23{,}6\,\mathrm{mm}$.','El recorrido total47,2mm dividido por5900m/s recupera8µs.','No proporciona tamaño del defectoniPOD; refracción,geometría y estructura pueden alterar la trayectoria.',[test('5900*8e-6/2',.0236,'m','v*t/2',{'v':'m/s','t':'s'})])
delta=1/math.sqrt(pi*100e3*(4*pi*1e-7)*35e6)
add('P28',11,'Profundidad pelicular','Estime profundidad de atenuación electromagnética en un conductor ideal y su cambio al cuadruplicar frecuencia.',r'$f=100\,\mathrm{kHz}$; $\mu=4\pi\times10^{-7}\,\mathrm{H/m}$; $\sigma_e=35\times10^6\,\mathrm{S/m}$.','Delta ydelta2.','Profundidad pelicular de conductor homogéneo.','Conductividad y permeabilidad constantes; geometría ideal; no se modeliza una sonda real.',[r'\delta=1/\sqrt{\pi f\mu\sigma_e},\quad\delta(4f)=\delta(f)/2.'],[r'Se usan100000Hz. La conductividad eléctrica se distingue de tensión mecánica.'],fr'$\delta={delta*1000:.5f}\,\mathrm{{mm}}$; a400kHz, $\delta={delta*500:.5f}\,\mathrm{{mm}}$.','La ley de escala con f^(−1/2)ofrece una comprobación separada.','La profundidad de atenuación no es profundidad máxima garantizada de detecciónni tamaño mínimo de grieta.',[test('1/sqrt(pi*100e3*(4*pi*1e-7)*35e6)',delta,'m','1/sqrt(pi*f*mu*sigmae)',{'f':'Hz','mu':'H/m','sigmae':'S/m'})])
add('P29',24,'Tasa de eventos y modelo exponencial','Una flota ficticia acumula exposición y eventos definidos. Estime tasa y fiabilidad de100horas bajo un modelo explícito.',r'$n=5$ eventos; $T=25000\,\mathrm h$; horizonte$t=100\,\mathrm h$.','lambda,MTBF yR(100).','Poisson para eventos y supervivencia exponencial de tasa constante como hipótesis.','Eventos comparables; exposición conocida; modelo homogéneo; no se da intervalo de confianza en este caso.',[r'\widehat\lambda=n/T,\quad MTBF=1/\widehat\lambda,\quad R(t)=e^{-\widehat\lambda t}.'],[r'$\widehat\lambda=5/25000$ h⁻¹; se mantiene el horizonte en horas.'],fr'$\widehat\lambda=2\times10^{{-4}}\,\mathrm{{h^{{-1}}}}$; $MTBF=5000\,\mathrm h$; $R(100)={math.exp(-.02):.7f}$.','El exponente es adimensional. R(0)=1y decrece con tpara tasa positiva.','Una tasa observada no prueba la ley exponencial ni fija un límite de vida.',[test('exp(-(5/25000)*100)',math.exp(-.02))])
add('P30',12,'Disponibilidad y espera logística','Compare disponibilidad del modelo que solo cuenta reparación activa con la de otro que incluye una espera media por evento.',r'$MTBF=600\,\mathrm h$; reparación activa3h; espera adicional12h.','Dos cocientes de disponibilidad.','Modelo estacionario simple de ciclos funcionamiento–restauración.','Tiempos medios representativos; no incluye mantenimiento programadoniotras paradas.',[r'A_i=600/(600+3),\quad A_{ext}=600/(600+3+12).'],[r'La segunda razón tiene otro alcance de tiempo; no se etiqueta como disponibilidad operacional completa.'],fr'$A_i={600/603:.7f}$; $A_{{ext}}={600/615:.7f}$.','Añadir espera disminuye disponibilidad. Ambos cocientes están entre0y1.','No se comparan directamente cifras si sus definiciones de parada difieren.',[test('600/(600+3)',600/603),test('600/(600+3+12)',600/615)])
cond=math.exp(-((700/1000)**2-(500/1000)**2))
add('P31',24,'Supervivencia condicional Weibull','Una vida ficticia sigue Weibull. Determine la probabilidad de sobrevivir200horas más,si ya se han alcanzado500sin fallo.',r'$\beta=2$; $\eta=1000\,\mathrm h$; $t_0=500\,\mathrm h$; $\Delta t=200\,\mathrm h$.','R(t0+dt)/R(t0).','Distribución Weibull de dos parámetros.','Modelo y población supuestos conocidos; no actualiza parámetros por observar una sola unidad.',[r'P(T>t_0+\Delta t\mid T>t_0)=\exp[-((t_0+\Delta t)/\eta)^\beta+(t_0/\eta)^\beta].'],[r'La probabilidad condicional usa700y500horas; no solo R(200).'],fr'Probabilidad condicional{cond:.7f}; $R(200)={math.exp(-.04):.7f}$,que no coincide.','Con beta=1la diferencia de exponentes depende solo del incremento y reaparece la propiedad sin memoria.','La ley Weibull no describe automáticamente un mecanismo de daño y requiere ajuste con datos y censura correctos.',[test('exp(-((700/1000)**2-(500/1000)**2))',cond)])
add('P32',24,'Cero fallos no significa tasa cero','En un modelo de Poisson se observan cero eventos. Obtenga el límite superior unilateral del95%para la tasa.',r'Exposición$T=15000\,\mathrm h$; $n=0$; nivel0,95.','lambda superior.','P(N=0)=exp(−lambdaT).','Modelo de Poisson homogéneo; observación completa y definición de evento constante.',[r'e^{-\lambda_U T}=0{,}05,\quad\lambda_U=-\ln(0{,}05)/T.'],[r'Se despeja el logaritmo natural y se conserva la exposición en horas.'],fr'$\lambda_U={-math.log(.05)/15000:.7g}\,\mathrm{{h^{{-1}}}}$.','SustituirlambdaUTda−ln0,05y la probabilidad de ceroeventoses0,05.','Es un límite estadístico bajo el modelo,no garantía individualni certificación de seguridad.',[test('-log(.05)/15000',-math.log(.05)/15000,'1/h')])
add('P33',22,'Frecuencia y orden de vibración','Un pico de frecuencia se observa junto a una velocidad de rotor. Calcule la orden cinemática y explique qué conclusión no permite.',r'$N=9600\,\mathrm{rpm}$; pico$f=480\,\mathrm{Hz}$.','Frecuencia de giro yorden.','Relación frecuencia–rotación.','Velocidad uniforme y referencia de rotor correcta; no se diagnostica el mecanismo.',[r'f_{rot}=N/60,\quad o=f/f_{rot}.'],[r'$f_{rot}=9600/60=160$ Hz; $o=480/160$.'],r'Frecuencia de giro160Hz; orden3.','Multiplicarordenporfrecuencia de giro recupera480Hz.','No determina desequilibrio,desalineaciónni límite de amplitud.',[test('480/(9600/60)',3)])
